// Generated by vibelang from src/features/chat/tab.ts; the migrate flow writes it again with each batch.
import { Effect, Layer } from "effect";
import { answerAskingTab } from "../../flows/askingTab.js";
import { copyToClipboard, takeBack } from "./actions.js";
import { copyChannel, editChannel } from "./contract.js";
import { CopyCall, EditCall } from "./schema.js";
// The tab's side of `chat/copy` and `chat/edit` (docs/features/chat.md#message-controls): every tab listens on the
// engine's chat channels, and only the tab that started a call's request answers it (src/flows/askingTab.ts), copying
// the message through the host's clipboard or taking the question back into its composer. Every other tab, and every
// other device, does nothing. Calls are answered one at a time.
/** Answers chat's channels of engine `name` for this tab's requests until its scope closes. */
export const tabChat = (host) => Layer.effectDiscard(Effect.gen(function* () {
    yield* answerAskingTab({
        channel: copyChannel(host.name),
        input: CopyCall,
        answer: ({ messageId }) => Effect.map(copyToClipboard(messageId), (outcome) => ({ outcome })),
    });
    yield* answerAskingTab({
        channel: editChannel(host.name),
        input: EditCall,
        answer: ({ questionId }) => Effect.map(takeBack(questionId), (outcome) => ({ outcome })),
    });
}));
